{"method": "GET", "path": "/", "requestBytes": 0, "status": 200, "response": "<!doctype html>\n<html lang=\"zh-CN\">\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<title>ScoreArena · 桌面规则游戏与赛事管理</title>\n<style>\n  :root { color-scheme: light; }\n  body { font-family: system-ui, sans-serif; max-width: 52rem; margin: 3rem auto; padding: 0 1rem; line-height: 1.7; color: #1f2933; }\n  h1 { margin-bottom: .25rem; }\n  .sub { color: #52606d; margin-top: 0; }\n  h2 { margin-top: 2.5rem; border-bottom: 1px solid #e4e7eb; padding-bottom: .35rem; }\n  a { color: #175b9c; }\n  form { background: #f8f9fb; border: 1px solid #e4e7eb; border-radius: .5rem; padding: 1.25rem 1.5rem; }\n  .field { display: grid; grid-template-columns: 9rem 1fr; gap: .75rem; align-items: center; margin-bottom: 1rem; }\n  label { font-weight: 600; }\n  input, select { font: inherit; padding: .4rem .55rem; border: 1px solid #cbd2d9; border-radius: .35rem; background: #fff; }\n  input:focus, select:focus { outline: 2px solid #9ec5fe; outline-offset: 1px; border-color: #175b9c; }\n  .hint { grid-column: 2; color: #616e7c; font-size: .9rem; margin: -.35rem 0 0; }\n  .actions { grid-column: 2; margin-top: .25rem; }\n  button { font: inherit; font-weight: 600; padding: .5rem 1.4rem; border: none; border-radius: .35rem; background: #175b9c; color: #fff; cursor: pointer; }\n  button:disabled { background: #9aa5b1; cursor: wait; }\n  .msg { margin: 1rem 0 0; padding: .6rem .9rem; border-radius: .35rem; display: none; }\n  .msg.show { display: block; }\n  .msg.error { background: #fde8e8; border: 1px solid #f5b5b5; color: #9b1c1c; }\n  .msg.ok { background: #e6f6ec; border: 1px solid #a7e0bd; color: #146134; }\n  .msg.warn { background: #fff8e6; border: 1px solid #f0d48a; color: #7c4a03; }\n  table { width: 100%; border-collapse: collapse; font-size: .95rem; }\n  th, td { text-align: left; padding: .55rem .6rem; border-bottom: 1px solid #e4e7eb; vertical-align: top; }\n  th { color: #52606d; font-size: .85rem; white-space: nowrap; }\n  td.id, code { font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace; font-size: .85rem; word-break: break-all; }\n  .empty { color: #616e7c; }\n  .filter-bar { display: flex; align-items: center; gap: .75rem; margin-bottom: 1rem; }\n  .filter-bar label { font-weight: 600; white-space: nowrap; }\n  .filter-bar input { flex: 1; max-width: 22rem; }\n  .filter-bar .filter-hint { color: #616e7c; font-size: .9rem; }\n  .skip-notice { background: #fff8e6; border: 1px solid #f0d48a; color: #7c4a03; padding: .6rem .9rem; border-radius: .35rem; margin: 0 0 1rem; }\n  .list-error { color: #9b1c1c; }\n  .badge { display: inline-block; padding: .05rem .55rem; border-radius: 999px; background: #fff3c4; color: #7c4a03; font-size: .85rem; }\n  .meta { color: #7b8794; font-size: .85rem; }\n</style>\n<main>\n  <h1>ScoreArena</h1>\n  <p class=\"sub\">桌面规则游戏与赛事管理</p>\n\n  <h2>创建公开房间</h2>\n  <form id=\"room-form\" novalidate>\n    <div class=\"field\">\n      <label for=\"name\">房间名称</label>\n      <input id=\"name\" name=\"name\" type=\"text\" autocomplete=\"off\"\n             placeholder=\"1–40 个字符，首尾空白会被去掉\" required>\n      <p class=\"hint\">名称会去掉首尾空白后保存，内部空格保留；长度按 Unicode 字符计。原始输入不限长，整理后不超过 40 个字符即可。</p>\n    </div>\n    <div class=\"field\">\n      <label for=\"game\">游戏规则</label>\n      <select id=\"game\" name=\"game\" required>\n        <option value=\"\" selected>请选择游戏规则…</option>\n        <option value=\"gomoku\">五子棋（gomoku）</option>\n        <option value=\"ludo\">飞行棋（ludo）</option>\n      </select>\n    </div>\n    <div class=\"field\">\n      <label for=\"capacity\">人数上限</label>\n      <select id=\"capacity\" name=\"capacity\" required disabled>\n        <option value=\"\" selected>请先选择游戏规则</option>\n      </select>\n      <p class=\"hint\" id=\"capacity-hint\">五子棋人数固定为 2 人；飞行棋允许 2 至 4 人。</p>\n    </div>\n    <div class=\"field\">\n      <label for=\"turnSeconds\">每步时间限制</label>\n      <input id=\"turnSeconds\" name=\"turnSeconds\" type=\"number\" step=\"1\" inputmode=\"numeric\"\n             placeholder=\"秒，0 表示不限时\" required>\n      <p class=\"hint\">以秒为单位：填 <strong>0</strong> 表示不限时；其他值必须是 10 至 600 之间的整数。</p>\n    </div>\n    <div class=\"field\">\n      <div></div>\n      <div class=\"actions\">\n        <button type=\"submit\" id=\"submit\">创建房间</button>\n      </div>\n    </div>\n    <p class=\"msg\" id=\"form-msg\" role=\"alert\"></p>\n  </form>\n\n  <h2>房间列表</h2>\n  <div class=\"filter-bar\">\n    <label for=\"room-filter\">名称筛选</label>\n    <input id=\"room-filter\" name=\"room-filter\" type=\"text\" autocomplete=\"off\"\n           placeholder=\"输入名称关键词，立即筛选已加载的房间\">\n    <span class=\"filter-hint\">只匹配名称文字，区分大小写；清空后恢复全部已加载房间。</span>\n  </div>\n  <div id=\"list-area\">\n    <p class=\"empty\" id=\"empty-tip\">还没有房间记录。</p>\n  </div>\n\n  <p class=\"meta\"><a href=\"/api/rooms\">查看房间列表接口</a> · <a href=\"/health\">服务状态</a></p>\n</main>\n\n<script>\n(function () {\n  var form = document.getElementById('room-form');\n  var gameSel = document.getElementById('game');\n  var capSel = document.getElementById('capacity');\n  var capHint = document.getElementById('capacity-hint');\n  var submitBtn = document.getElementById('submit');\n  var formMsg = document.getElementById('form-msg');\n  var listArea = document.getElementById('list-area');\n  var emptyTip = document.getElementById('empty-tip');\n  var filterInput = document.getElementById('room-filter');\n\n  // 映射表必须是无原型对象：历史值里可能恰好存着 \"constructor\"、\"toString\"、\n  // \"__proto__\" 这类字符串，普通对象字面量会沿原型链查到内置函数或\n  // Object.prototype，反而把函数源码或 [object Object] 当成中文映射显示。\n  // 无原型对象查这些键一律得到 undefined，于是按未知值逐字回显原文。\n  var GAME_LABELS = Object.create(null);\n  GAME_LABELS.gomoku = '五子棋';\n  GAME_LABELS.ludo = '飞行棋';\n  var STATUS_LABELS = Object.create(null);\n  STATUS_LABELS.waiting = '未开始';\n\n  // 按所选规则重建人数上限选项。\n  function syncCapacity() {\n    var game = gameSel.value;\n    var prev = capSel.value;\n    capSel.innerHTML = '';\n    if (game === 'gomoku') {\n      capSel.disabled = false;\n      addOption('', '固定 2 人');\n      addOption('2', '2 人');\n      capSel.value = '2';\n      capHint.textContent = '五子棋人数上限固定为 2 人。';\n    } else if (game === 'ludo') {\n      capSel.disabled = false;\n      addOption('', '请选择人数上限…');\n      [2, 3, 4].forEach(function (n) { addOption(String(n), n + ' 人'); });\n      capSel.value = (prev === '2' || prev === '3' || prev === '4') ? prev : '';\n      capHint.textContent = '飞行棋人数上限允许 2 至 4 人。';\n    } else {\n      capSel.disabled = true;\n      addOption('', '请先选择游戏规则');\n      capHint.textContent = '五子棋人数固定为 2 人；飞行棋允许 2 至 4 人。';\n    }\n  }\n\n  function addOption(value, text) {\n    var opt = document.createElement('option');\n    opt.value = value;\n    opt.textContent = text;\n    capSel.appendChild(opt);\n  }\n\n  gameSel.addEventListener('change', syncCapacity);\n\n  function showMessage(kind, text) {\n    formMsg.className = 'msg show ' + kind;\n    formMsg.textContent = text;\n  }\n  function clearMessage() {\n    formMsg.className = 'msg';\n    formMsg.textContent = '';\n  }\n\n  // 与服务端 strings.TrimSpace（Go unicode.IsSpace）完全一致的首尾空白范围：\n  // 包含 U+0085、U+00A0 等，但不包含 U+FEFF（保留并计入长度）。\n  // 不能用 JS 自带的 trim()：它会多去掉 U+FEFF，又漏掉 U+0085。\n  var EDGE_SPACE = '[\\\\u0009-\\\\u000D\\\\u0020\\\\u0085\\\\u00A0\\\\u1680\\\\u2000-\\\\u200A\\\\u2028\\\\u2029\\\\u202F\\\\u205F\\\\u3000]';\n  var LEADING_SPACE = new RegExp('^' + EDGE_SPACE + '+');\n  var TRAILING_SPACE = new RegExp(EDGE_SPACE + '+$');\n  function trimName(value) {\n    return value.replace(LEADING_SPACE, '').replace(TRAILING_SPACE, '');\n  }\n\n  // 与服务端一致的提交前校验；服务端仍会再次校验。\n  // 输入表单原始值，返回 { error } 或 { payload }：漏填要明确报错，绝不补默认值；\n  // 名称只含会被去掉的首尾空白时同样视为空。通过校验的 payload 中名称仍是\n  // 用户原始输入（不由页面整理），时间与人数各只转换一次。\n  function checkForm(raw) {\n    var nameLen = Array.from(trimName(raw.name)).length;\n    if (nameLen === 0) return { error: '房间名称不能为空。' };\n    if (!raw.game) return { error: '请选择游戏规则。' };\n    if (raw.capacity === '') return { error: '请选择人数上限。' };\n    if (raw.turnSeconds === '') return { error: '请填写每步时间限制（0 表示不限时）。' };\n    if (!/^-?\\d+$/.test(raw.turnSeconds)) return { error: '时间限制必须是整数秒，不能含小数。' };\n\n    // 通过必填与整数格式检查后再转换：空值不会变成 0，不合法文字不会变成秒数。\n    var capacity = parseInt(raw.capacity, 10);\n    var turnSeconds = Number(raw.turnSeconds);\n\n    if (nameLen > 40) return { error: '房间名称去掉首尾空白后不能超过 40 个字符。' };\n    if (raw.game !== 'gomoku' && raw.game !== 'ludo') return { error: '请选择游戏规则。' };\n    if (raw.game === 'gomoku' && capacity !== 2) return { error: '五子棋的人数上限固定为 2 人。' };\n    if (raw.game === 'ludo' && !(capacity >= 2 && capacity <= 4)) {\n      return { error: '飞行棋的人数上限必须为 2 至 4 人。' };\n    }\n    if (turnSeconds !== 0 && !(turnSeconds >= 10 && turnSeconds <= 600)) {\n      return { error: '每步时间限制只能填 0（不限时）或 10 至 600 之间的整数秒。' };\n    }\n\n    return {\n      payload: {\n        name: raw.name,\n        game: raw.game,\n        capacity: capacity,\n        turnSeconds: turnSeconds\n      }\n    };\n  }\n\n  // 是否已有一次创建请求在途。等待期间表单四项仍可继续编辑（规则与人数\n  // 的联动照常生效），但不能再次提交：按钮在本次提交及随后的列表刷新\n  // 完成前保持禁用，这里再加一道防线，阻止通过回车键等方式触发第二次\n  // 提交。等待期间的编辑只影响表单本身：既不改变已提交的配置，也不会\n  // 自动再发出一次创建请求。\n  var submitting = false;\n\n  // 读取表单四项在页面上的实际填写值（名称保留首尾空白的原貌，不做整理）。\n  // 提交时与响应到达时各读一次并逐项比较，据此决定成功后是否复位表单。\n  function nameInput() { return document.getElementById('name'); }\n  function turnSecondsInput() { return document.getElementById('turnSeconds'); }\n  function readFormValues() {\n    return {\n      name: nameInput().value,\n      game: gameSel.value,\n      capacity: capSel.value,\n      turnSeconds: turnSecondsInput().value\n    };\n  }\n\n  form.addEventListener('submit', function (event) {\n    event.preventDefault();\n    if (submitting) return;\n    clearMessage();\n\n    var result = checkForm({\n      name: nameInput().value,\n      game: gameSel.value,\n      capacity: capSel.value,\n      turnSeconds: turnSecondsInput().value.trim()\n    });\n    if (result.error) { showMessage('error', result.error); return; }\n\n    submit(result.payload);\n  });\n\n  // 表单复位到初始状态：名称与时间清空、规则未选、人数不可填写。\n  // 仅在创建成功且等待期间四项填写值与提交时完全一致时调用。\n  function resetForm() {\n    form.reset();\n    syncCapacity();\n  }\n\n  function submit(payload) {\n    submitting = true;\n    submitBtn.disabled = true;\n\n    // 点击提交瞬间四项的实际填写值快照。本次房间固定按 payload（即点击时\n    // 的配置）创建；响应到达时再读一次当前值与之逐项比较。\n    var submittedValues = readFormValues();\n\n    fetch('/api/rooms', {\n      method: 'POST',\n      headers: { 'Content-Type': 'application/json' },\n      body: JSON.stringify(payload)\n    }).then(function (resp) {\n      // 记录正文是否完整读出并解析为 JSON。状态码已收到（如 201）但正文\n      // 为空、被截断或读取中断时，bodyOk 为 false：此时不能拿解析失败的\n      // 空数据冒充创建结果（否则会显示“编号：undefined”）。\n      return resp.json().then(function (data) {\n        return { ok: resp.ok, status: resp.status, data: data, bodyOk: true };\n      }, function () {\n        return { ok: resp.ok, status: resp.status, data: null, bodyOk: false };\n      });\n    }).then(function (result) {\n      if (result.ok && result.status === 201) {\n        // 只有正文完整读出、能解析且带有非空编号，才算拿到本次创建结果。\n        var createdId = result.bodyOk && result.data &&\n          typeof result.data.id === 'string' && result.data.id !== ''\n          ? result.data.id : null;\n\n        if (createdId === null) {\n          // 已收到 201 但创建结果未能确认：房间可能已经在服务端保存。\n          // 不承诺创建失败、不显示成功编号、不凭空拼房间或猜编号，\n          // 不自动重发本次提交，也不清空或改动房间列表；表单四项以页面\n          // 当前实际填写为准整体保留（含等待期间的修改，不整理名称首尾\n          // 空白、不补齐未填项），提醒用户先刷新页面核对列表再决定。\n          showMessage('warn', '创建结果未能确认：服务已返回成功状态，但回应内容未能完整读取，' +\n            '房间可能已经保存。请先刷新页面查看房间列表，确认是否已创建后，再决定是否重新提交。');\n          return;\n        }\n\n        var okText = '房间已创建，编号：' + createdId;\n\n        // 是否复位以页面当前实际填写值为准，与提交时快照逐项比较：\n        // 四项全部一致（含等待期间改过又完整恢复）才恢复初始表单；\n        // 任一项不同——哪怕只动了名称的首尾空白——都整体保留当前四项\n        // 及其对应的人数选择状态，不能只留改过的项，也不能把其他项\n        // 恢复成旧配置；内容没填完整同样原样保留、不自动补齐。\n        var currentValues = readFormValues();\n        var unchanged = currentValues.name === submittedValues.name &&\n          currentValues.game === submittedValues.game &&\n          currentValues.capacity === submittedValues.capacity &&\n          currentValues.turnSeconds === submittedValues.turnSeconds;\n\n        if (unchanged) {\n          showMessage('ok', okText);\n          resetForm();\n        } else {\n          // 本次房间已按提交时的配置创建并生成编号；表单中是等待期间\n          // 继续填写、尚未提交的新配置，不会自动创建下一间房，完整保留\n          // 供用户处理完成后直接再次提交。\n          showMessage('ok', okText + '。表单中当前填写的内容尚未提交，不会自动创建房间；' +\n            '如需创建下一间，可直接点击“创建房间”。');\n        }\n        return loadRooms();\n      }\n      // 创建失败（被服务拒绝）：不触碰表单，等待期间的最新填写原样保留，\n      // 不回退到提交时的值，仅显示服务给出的原因。\n      var reason = result.data && result.data.error ? result.data.error\n                 : ('创建失败（HTTP ' + result.status + '）');\n      showMessage('error', reason);\n    }).catch(function () {\n      // 连接失败同样保留当时最新的填写内容。\n      showMessage('error', '无法连接服务，请确认服务仍在运行后重试。');\n    }).finally(function () {\n      submitting = false;\n      submitBtn.disabled = false;\n    });\n  }\n\n  // 创建时间列的三种正常展示（对象/数组已由 buildRoomRow 统一判为异常，\n  // 不会进入这里）：\n  //   1. 能解析成有效日期的字符串：按浏览器本地时区显示\n  //      YYYY-MM-DD HH:mm:ss（带时区偏移的时间换算成实际对应的本地时刻，\n  //      不把原串里的时分当本地时间），悬浮提示保留接口返回的原始字符串；\n  //   2. 无法解析的非空字符串：原文直接显示在单元格中（textContent 保证\n  //      尖括号等字符只作为文字呈现），不替换为当前时间，不附悬浮说明；\n  //   3. 字段缺失、null 或空字符串：单元格留空且没有悬浮说明，\n  //      绝不由页面生成 undefined 或 Invalid Date。\n  function renderTimeCell(td, value) {\n    if (value == null || value === '') return;\n\n    var d = new Date(value);\n    if (isNaN(d.getTime())) {\n      td.textContent = typeof value === 'string' ? value : String(value);\n      return;\n    }\n\n    var pad = function (n) { return String(n).padStart(2, '0'); };\n    td.textContent = d.getFullYear() + '-' + pad(d.getMonth() + 1) + '-' + pad(d.getDate()) +\n      ' ' + pad(d.getHours()) + ':' + pad(d.getMinutes()) + ':' + pad(d.getSeconds());\n    td.title = typeof value === 'string' ? value : String(value);\n  }\n\n  // 只有 JSON 对象能作为房间行；null、字符串、数字、布尔值和数组都跳过。\n  // 不按创建表单的规则重新判定历史记录：对象带多少附加字段都照常展示，\n  // 也不检查其字段是否完整或合法（各单元格沿用现有兜底显示）。\n  function isRoomRecord(value) {\n    return value !== null && typeof value === 'object' && !Array.isArray(value);\n  }\n\n  function appendSkipNotice(skipped, allSkipped) {\n    var p = document.createElement('p');\n    p.className = 'skip-notice';\n    if (allSkipped) {\n      p.textContent = '没有可展示的房间。本次返回的房间记录中有 ' + skipped +\n        ' 条无法作为房间显示，已全部跳过；原始数据仍保留在服务端，未被删除或改写。';\n    } else {\n      p.textContent = '有 ' + skipped + ' 条房间记录无法作为房间显示，已跳过；' +\n        '原始数据仍保留在服务端，未被删除或改写。';\n    }\n    listArea.appendChild(p);\n  }\n\n  // 历史记录的某个展示字段若被存成 JSON 对象或数组，该单元格统一显示\n  // “字段格式异常”，不展开其内部内容；异常只影响所在单元格，绝不能抛出\n  // 异常拖垮整行乃至整份列表。null、字符串、数字、布尔值及缺失字段都不算\n  // 异常，仍走各列原有的展示与兜底。\n  var BAD_FIELD_TEXT = '字段格式异常';\n  function isAbnormalField(value) {\n    return value !== null && typeof value === 'object';\n  }\n  function markBadCell(td) {\n    td.textContent = BAD_FIELD_TEXT;\n  }\n\n  function appendBadge(td, text) {\n    var badge = document.createElement('span');\n    badge.className = 'badge';\n    badge.textContent = text;\n    td.appendChild(badge);\n  }\n\n  // 七列的展示定义，顺序即表格列顺序（表头也由同一份定义生成）。每列只\n  // 描述“正常值如何显示”（含各列原有的兜底行为）；对象/数组的异常判定\n  // 与替换由 buildRoomRow 统一处理，不在各列重复维护。个别列可用\n  // renderBad 保留原有容器（如状态列的徽标），缺省时整格替换为异常文案。\n  var ROOM_COLUMNS = [\n    {\n      key: 'id',\n      label: '房间编号',\n      className: 'id',\n      render: function (td, value) { td.textContent = value || ''; }\n    },\n    {\n      key: 'name',\n      label: '名称',\n      render: function (td, value) { td.textContent = value || ''; }\n    },\n    {\n      key: 'game',\n      label: '规则',\n      render: function (td, value) {\n        td.textContent = GAME_LABELS[value] || value || '';\n      }\n    },\n    {\n      key: 'capacity',\n      label: '人数上限',\n      render: function (td, value) {\n        td.textContent = (value != null ? value : '') + ' 人';\n      }\n    },\n    {\n      key: 'turnSeconds',\n      label: '时间限制',\n      render: function (td, value) {\n        td.textContent = value === 0 ? '不限时' : value + ' 秒';\n      }\n    },\n    {\n      key: 'status',\n      label: '状态',\n      render: function (td, value) {\n        appendBadge(td, STATUS_LABELS[value] || value || '');\n      },\n      // 异常状态仍在原有徽标中显示提示文案。\n      renderBad: function (td) { appendBadge(td, BAD_FIELD_TEXT); }\n    },\n    {\n      key: 'createdAt',\n      label: '创建时间',\n      render: renderTimeCell\n      // 无 renderBad：异常创建时间只显示异常文案，不附加日期悬浮说明\n      // （不设置 title）。\n    }\n  ];\n\n  // 逐列渲染一个房间行：任何字段异常都只替换该单元格，其余字段照常显示。\n  function buildRoomRow(r) {\n    var tr = document.createElement('tr');\n    ROOM_COLUMNS.forEach(function (col) {\n      var td = document.createElement('td');\n      if (col.className) td.className = col.className;\n      var value = r[col.key];\n      if (isAbnormalField(value)) {\n        if (col.renderBad) col.renderBad(td);\n        else markBadCell(td);\n      } else {\n        col.render(td, value);\n      }\n      tr.appendChild(td);\n    });\n    return tr;\n  }\n\n  function renderRooms(rooms) {\n    listArea.innerHTML = '';\n\n    var validRooms = [];\n    var skipped = 0;\n    rooms.forEach(function (r) {\n      if (isRoomRecord(r)) validRooms.push(r);\n      else skipped++;\n    });\n\n    if (!validRooms.length) {\n      if (skipped > 0) {\n        appendSkipNotice(skipped, true);\n      } else {\n        var pEmpty = document.createElement('p');\n        pEmpty.className = 'empty';\n        pEmpty.textContent = '还没有房间记录。';\n        listArea.appendChild(pEmpty);\n      }\n      return;\n    }\n\n    // 跳过提示按本次完整返回内容统计：被关键词隐藏的房间仍是正常房间，\n    // 绝不计为异常记录；提示始终先于表格或无匹配说明出现。\n    if (skipped > 0) appendSkipNotice(skipped, false);\n\n    // 非空关键词只对接口返回的名称字符串做连续文字匹配（区分英文大小写）：\n    // 内部空格、中文、表情、尖括号与